#!/usr/bin/env python3
import subprocess,time,json,urllib.request
from pathlib import Path
ROOT="/Users/Shared/WorkspaceBersama/ChatGPTHeadlessPool"
rows=[]
for c in ("C","D"):
    p=subprocess.Popen(["python3",f"{ROOT}/launch_cluster.py",c,"0","0","1792","1120"],cwd=ROOT,
                       stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
    rows.append({"cluster":c,"pid":p.pid})
deadline=time.time()+55
ports=[19427,19437,19438]
state={}
while time.time()<deadline:
    for port in ports:
        if state.get(port,{}).get("alive"): continue
        try:
            with urllib.request.urlopen(f"http://127.0.0.1:{port}/json/list",timeout=1) as r:
                pages=json.loads(r.read().decode())
            state[port]={"alive":True,"pages":[{"id":x.get("id"),"title":x.get("title"),"url":x.get("url")} for x in pages if x.get("type")=="page"]}
        except Exception as e:
            state[port]={"alive":False,"error":type(e).__name__}
    if all(state.get(p,{}).get("alive") for p in ports): break
    time.sleep(1)
print(json.dumps({"launches":rows,"ports":state},ensure_ascii=False))
Path(__file__).unlink(missing_ok=True)
